void modify(const std::string &key, Callable &&handler)
{
    std::lock_guard<std::mutex> lck(mutex_);
    auto it = sessionMap_.find(key);
    if (it != sessionMap_.end())
    {
        if (typeid(T) == it->second.type())
        {
            handler(*(std::any_cast<T>(&(it->second))));
        }
        else
        {
            LOG_ERROR << "Bad type";
        }
    }
